def choose_move(observation):
    o = observation if isinstance(observation, dict) else {}
    W = int(o.get("grid_width", 0) or 0)
    H = int(o.get("grid_height", 0) or 0)

    def pos(v, d=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return (int(v[0]), int(v[1]))
            except Exception:
                return d
        return d

    def sgn(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    me = pos(o.get("self_position"))
    opp = pos(o.get("opponent_position"), (W // 2, H // 2))
    obs_set = set()
    for p in o.get("obstacles") or []:
        obs_set.add(pos(p, None))
    if None in obs_set:
        obs_set.discard(None)

    best = None
    bestv = None
    for r in o.get("resources") or []:
        p = pos(r, None)
        if p is None:
            continue
        v = dist(me, p) * 3 - dist(opp, p) * 2
        if best is None or v < bestv:
            best, bestv = p, v

    cand = []
    if best is not None:
        cand.append([sgn(best[0] - me[0]), sgn(best[1] - me[1])])
        cand.append([sgn(best[0] - me[0]), 0])
        cand.append([0, sgn(best[1] - me[1])])
    cand += [[sgn(me[0] - opp[0]), sgn(me[1] - opp[1])], [sgn(me[0] - opp[0]), 0], [0, sgn(me[1] - opp[1])]]
    cand += [[1, 0], [-1, 0], [0, 1], [0, -1], [0, 0]]

    for dx, dy in cand:
        nx, ny = me[0] + dx, me[1] + dy
        if 0 <= nx < W and 0 <= ny < H and (nx, ny) not in obs_set:
            return [dx, dy]
    return [0, 0]

